"""Run original mechanism fixture, not baseline/candidate model outputs."""
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent
report = {"evidence_kind": "authored_fixture_runtime", "checks": [],
          "limitations": ["Not generated by either skill version", "No model quality comparison or human blind review",
                          "Fallback forced by CSS override, not an unsupported browser", "No pointer-safe-zone or drag implementation tested",
                          "Runner targets one msedge channel; no engine launched if the import fails",
                          "No browser compatibility matrix"]}


def check(name, passed, actual=None):
    report["checks"].append({"name": name, "passed": bool(passed), "actual": actual})


def run():
    from playwright.sync_api import sync_playwright

    with sync_playwright() as playwright:
        browser = playwright.chromium.launch(channel="msedge", headless=True)
        report["browser"] = {"channel": "msedge", "version": browser.version, "headless": True}
        context = browser.new_context(viewport={"width": 1440, "height": 900})
        page = context.new_page()
        errors = []
        page.on("pageerror", lambda error: errors.append(str(error)))
        page.goto((ROOT / "mechanism-probe.html").as_uri())
        report["user_agent"] = page.evaluate("navigator.userAgent")
        report["font"] = page.locator("body").evaluate("el => getComputedStyle(el).fontFamily")
        for width, height in [(1440, 900), (390, 844), (320, 740)]:
            page.set_viewport_size({"width": width, "height": height})
            overflow = page.evaluate("document.documentElement.scrollWidth - innerWidth")
            check(f"overflow-{width}", overflow <= 1, overflow)
            page.screenshot(path=str(ROOT / f"runtime-{width}.png"), full_page=True)
        page.set_viewport_size({"width": 1440, "height": 900})
        button_before = page.locator("#refresh").bounding_box()
        number_before = page.locator("#counter").bounding_box()
        page.locator("#refresh").click()
        check("loading-box-stable", page.locator("#refresh").bounding_box()["width"] == button_before["width"])
        check("number-box-stable", page.locator("#counter").bounding_box()["width"] == number_before["width"])
        glyphs = page.locator("#counter").evaluate("""el => {
          const widths = ['1111','8888'].map(text => { const s=document.createElement('span');
            s.style.font=getComputedStyle(el).font; s.style.fontVariantNumeric='tabular-nums';
            s.textContent=text; document.body.append(s); const w=s.getBoundingClientRect().width; s.remove(); return w; });
          return widths;
        }""")
        check("actual-font-tabular-digits", abs(glyphs[0] - glyphs[1]) < .5, glyphs)
        page.locator("#log").evaluate("el => el.scrollTop = 0")
        composer_before = page.locator("#composer").bounding_box()
        page.locator("#append").click()
        check("scroll-away-preserved", page.locator("#log").evaluate("el => el.scrollTop") == 0)
        check("composer-geometry-stable", page.locator("#composer").bounding_box() == composer_before)
        page.locator("#latest").click()
        page.locator("#append").click()
        distance = page.locator("#log").evaluate("el => el.scrollHeight - el.scrollTop - el.clientHeight")
        check("following-bottom-preserved", distance <= 2, distance)
        for _ in range(3):
            page.locator("#toggle").click()
        check("interrupted-open-close-open", page.locator("#toggle").get_attribute("aria-expanded") == "true")
        page.locator("#toggle").focus()
        page.keyboard.press("Tab")
        check("keyboard-action-and-focus-immediate", page.evaluate("document.activeElement.id") == "action")
        ring = page.locator("#action").evaluate("el => ({ width:getComputedStyle(el).outlineWidth, style:getComputedStyle(el).outlineStyle })")
        check("focus-ring-visible", ring["style"] != "none" and ring["width"] != "0px", ring)
        page.keyboard.press("Escape")
        check("escape-restores-focus", page.evaluate("document.activeElement.id") == "toggle" and page.locator("#overlay").get_attribute("inert") is not None)
        page.emulate_media(reduced_motion="reduce")
        page.locator("#toggle").click()
        duration = page.locator("#overlay").evaluate("el => getComputedStyle(el).transitionDuration")
        check("reduced-motion-no-transition", duration == "0s", duration)
        page.locator("#toggle").click()
        check("reduced-motion-functional-close", page.locator("#overlay").get_attribute("inert") is not None)
        page.locator("#pay").click()
        check("confirmation-retained", page.locator("dialog").evaluate("el => el.open") and page.evaluate("document.activeElement.id") == "cancel")
        page.keyboard.press("Escape")
        check("dialog-focus-return", page.evaluate("document.activeElement.id") == "pay")
        page.evaluate("document.documentElement.classList.add('no-enhance')")
        for theme in ["light", "dark"]:
            page.evaluate("theme => document.documentElement.dataset.theme = theme", theme)
            style = page.locator(".glass").evaluate("el => ({background:getComputedStyle(el).backgroundColor, color:getComputedStyle(el).color, filter:getComputedStyle(el).backdropFilter})")
            check(f"opaque-fallback-{theme}", style["filter"] == "none" and style["background"] in ["rgb(255, 255, 255)", "rgb(32, 32, 32)"], style)
        check("no-page-errors", not errors, errors)
        mobile = browser.new_context(viewport={"width": 390, "height": 844}, has_touch=True, is_mobile=True)
        touch_page = mobile.new_page()
        touch_page.goto((ROOT / "mechanism-probe.html").as_uri())
        touch_page.locator("#toggle").tap()
        check("touch-disclosure-accessible", touch_page.locator("#toggle").get_attribute("aria-expanded") == "true")
        touch_page.locator("#pay").tap()
        check("touch-confirmation-accessible", touch_page.locator("dialog").evaluate("el => el.open"))
        browser.close()


if __name__ == "__main__":
    try:
        run()
    except Exception as error:
        report["error"] = str(error)
        report["status"] = "missing evidence"
    report["run_at"] = datetime.now(timezone.utc).isoformat()
    report["ok"] = "error" not in report and all(item["passed"] for item in report["checks"])
    (ROOT / "runtime-results.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, ensure_ascii=True, indent=2))
    raise SystemExit(0 if report["ok"] else 1)
